import sys

from mcp import ClientSession, StdioServerParameters
from mcp.client.stdio import stdio_client


async def run(query: str = "Python"):
    server = StdioServerParameters(
        command="npx",
        args=["-y", "wikipedia-mcp"],
    )

    try:
        async with stdio_client(server) as (read, write):
            async with ClientSession(read, write) as session:
                await session.initialize()

                tools_result = await session.list_tools()
                tools = tools_result.tools
                print(f"已连接 Wikipedia MCP 服务器，发现 {len(tools)} 个工具：")

                search_tool = None
                for tool in tools:
                    print(f"  - {tool.name}: {tool.description or ''}")
                    if "search" in tool.name.lower():
                        search_tool = tool.name

                if search_tool:
                    print(f"\n正在调用工具 '{search_tool}' 搜索 '{query}' ...")
                    result = await session.call_tool(
                        search_tool,
                        arguments={"query": query},
                    )
                    for item in result.content:
                        if hasattr(item, "text"):
                            print(item.text)
                        else:
                            print(item)
                else:
                    print("\n未找到搜索工具，仅完成工具列表测试。")

    except FileNotFoundError:
        print("错误：未找到 npx，请安装 Node.js 并确保 npx 在 PATH 中。")
    except Exception as exc:
        print(f"测试失败：{type(exc).__name__}: {exc}")


def main():
    query = sys.argv[1] if len(sys.argv) > 1 else "Python"
    asyncio.run(run(query))


if __name__ == "__main__":
    main()

